                    float4 out1 = make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]);
                    __stcs(reinterpret_cast<float4*>(C + (int64_t)gr * N + gc1), out1);
                } else {
                    #pragma unroll
                    for (int j = 4; j < TN; ++j)
                        if (gc1 + (j - 4) < N) C[(int64_t)gr * N + gc1 + (j - 4)] = acc[i][j];
                }
            }
        }
    } else {
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int gr = block_row + thread_row + (i << 4);
            if (gr < M) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    int gc = block_col + thread_col + (j < 4 ? j : 64 + (j - 4));
                    if (gc < N) C[(int64_t)gr * N + gc] = acc[i][j];
                }
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 &&
                B.scalar_type() == torch::kFloat32, "float32 expected");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "CUDA tensors expected");

    auto Ac = A.contiguous();
    auto Bc = B.contiguous();

    const int M = (int)Ac.size(0);
    const int K = (int)Ac.size(1);
    TORCH_CHECK((int)Bc.size(0) == K, "inner dimensions must match");
    const int N = (int)Bc.size(1);

    auto C = torch::empty({M, N}, Ac.options());
    if (M == 0 || N == 0) return C;
    if (K == 0) { C.zero_(); return C; }

    dim3 threads(BN / TN, BM / TM);              // 16 x 16 = 256 threads
    dim3 blocks((N + BN - 1) / BN, (M + BM - 1) / BM);

    auto stream = at::cuda::getCurrentCUDAStream();
    matmul_tall_skinny_kernel<<<blocks, threads, 0, stream>>>(
        Ac.data_ptr<float>(), Bc.data_ptr<float>(), C.data_ptr<float>(),
        M, N, K);
    return C;
}
"""

cpp_src = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

_mod = load_inline(
    name="tall_skinny_matmul_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["matmul_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model with a custom CUDA kernel for the tall-and-skinny matmul C = A @ B
    (e.g. A: (32768, 32), B: (32, 32768)). The kernel exploits the tiny
    reduction dimension (K=32) with a single-pass tiled kernel using shared
    memory tiling, register blocking (4x4 per thread) and vectorized I/O.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._matmul = _mod.matmul_cuda

    def forward(self, A, B):
        if A.is_cuda and B.is_cuda:
            return self._matmul(A, B)
        # fallback so the module is still correct with CPU inputs
        return self._matmul(A.cuda(), B.cuda()).to(A.device)
